'use strict';
const FieldOps={
 ops:null,heard:[],bonus:0,serial:0,seenSounds:new Set(),state:null,
 reset(){this.lightOff=false;this.bonus=0;this.heard=[];this.state=null;this.seenSounds.clear();if(!player)return;Object.assign(player,{id:'solo',type:player.weapon,mod:null,modStock:2,task:null});for(const e of enemies)e.opsId='npc'+(++this.serial);if(gameMode!=='solo'){this.ops=null;return}
  this.ops=new TZTactics.Operations({world:worldGeometry,actors:()=>{for(const e of enemies){e.opsId||='npc'+(++this.serial);e.id=e.opsId}return [player,...enemies]},group:a=>a===player?'solo':'raiders',gun:a=>a===player?player:null,obstacles:()=>[...Expedition.containers,...crates,...airdrops],geometry:w=>{buildMap(activeMap.id,w.crane);this.ops.world=worldGeometry;for(const e of enemies){e.path=[];e.repath=0}},reward:(a,n,value)=>{if(a!==player)return false;this.bonus+=value;player.modStock=Math.min(3,player.modStock+1);return true},notice:text=>toast(text.replace(' +2 目标分 / +300 物资价值',' +300 撤离奖金'),3),noise:(source,kind,radius)=>{if(source===player&&playerHidden()&&kind!=='lock')return;if(source===player||kind==='alarm')for(const e of enemies)if(e.hp>0&&dist(source,e)<radius*(los(source,e)?1:.6)){e.engaged=true;e.alertUntil=time+7;e.lastKnown=worldGeometry.nearest(source.x,source.y);e.repath=0}}});
 },
 lighting(now=time){const off=activeMap.id==='sector07'&&worldGeometry.darkUntil>now;if(off!==this.lightOff){this.lightOff=off;Art.terrain(mapCanvas.getContext('2d'))}},
 carried(){return gameMode==='solo'?this.ops?.objective?.carrier===player?.id:!!this.state?.objective?.yours},
 shot(a){if(gameMode!=='solo'||!this.ops)return;this.ops.time=time;this.ops.emit(a,'shot',TZTactics.gunStats(a.weapon,a.mod).soundRange||620)},
 interact(){if(gameMode!=='solo'||!running||paused||!this.ops)return false;const success=this.ops.interact(player);if(success){Expedition.searching=null;player.reload=0}return success},
 install(){if(!running||paused||player.hp<=0)return;const mod=$('modSelect').value||'suppressor';if(gameMode==='multi'){TZNet.send({type:'mod',mod});return}player.type=player.weapon;if(this.ops?.install(player,mod)){Expedition.searching=null;toast('原地安装配件，移动或开火会中断')}else toast('需要改装包和常规武器，且不能正在换弹')},
 update(dt){if(!this.ops||gameMode!=='solo')return;player.type=player.weapon;player.firing=mouse.down||sticks.aim.id!==null||Math.hypot(sticks.aim.x,sticks.aim.y)>.35;this.ops.time=time-dt;this.ops.tick(dt);this.heard=this.ops.hear(player);this.state=this.ops.snapshot(player);worldGeometry.darkUntil=this.ops.darkUntil;this.lighting()},
 sync(s){time=s.time;this.state=s.ops;this.heard=s.sounds||[];if(s.ops){if(worldGeometry.crane!==s.ops.crane)buildMap(s.mapId,s.ops.crane);worldGeometry.darkUntil=s.ops.darkUntil;this.lighting(s.time)}if(s.notice&&s.notice!==this.lastNotice){toast(s.notice,3);this.lastNotice=s.notice}},
 target(){if(gameMode==='solo')return this.ops?.targets(player)[0]||null;const s=TZNet.state;if(!s)return null;const friend=s.peers.find(a=>a.ally&&a.downed&&dist(a,player)<62&&los(a,player));if(friend)return {...friend,label:'救援 '+friend.name};const o=s.ops?.objective,m=s.ops?.mechanism,list=[];if(m&&m.readyAt<=s.time)list.push(m);if(o?.kind==='intel'){if(!o.carried)list.push({...o,label:'拾取情报'});else if(o.yours)list.push({...o.end,label:'上传情报'})}return list.filter(a=>dist(player,a)<62&&los(player,a)).sort((a,b)=>dist(player,a)-dist(player,b))[0]||null},
 hud(){if(!player)return;const s=gameMode==='solo'?this.ops?.snapshot(player):this.state,o=s?.objective;const labels={intel:'情报运送',escort:'运输车护送',beacon:'信标占领'};
  $('opsHUD').hidden=!running;$('modPanel').hidden=!running||player.hp<=0;$('modStatus').textContent=(TZTactics.MODS[player.mod]?.name||'未装配件')+' · 改装包 '+(player.modStock||0);$('installMod').disabled=!(player.modStock>0)||!!W[player.weapon].limited||player.reload>0;
  $('objectiveText').textContent=o?`${labels[o.kind]} · ${Math.max(0,Math.ceil(o.expires-time))}s`:'下一目标 · '+Math.max(0,Math.ceil((s?.nextObjective||20)-time))+'s';
  $('objectiveHint').textContent=o?(o.kind==='intel'?(o.yours?'携带中：去上传点，方位会定时暴露':o.carried?'情报已被带走，注意方位提示':'到标记处拾取情报，再送往上传点'):o.contested?'敌我同时在场 · 争夺中':o.kind==='escort'?'靠近运输车推进，敌人靠近则停止':'留在圈内占领 · '+Math.min(100,Math.round(o.progress/8*100))+'%'):(gameMode==='solo'?'任务奖金 300 · 成功撤离后保存':(TZNet.state?.settings?.victory==='kills'?'目标奖励：物资 / 改装包 · 不计人头':'目标奖励：2 目标分 + 300 物资价值'));
  const m=s?.mechanism;$('mechanismText').textContent=m?m.label+' · '+(time<m.activeUntil?'已启动':time<m.readyAt?'冷却 '+Math.ceil(m.readyAt-time)+'s':'可使用 [E]'):'';
  const target=this.target(),task=s?.task;if(task||target){$('searchButton').style.display=player.hp>0?'block':'none';$('searchButton').textContent=task?task.label+' '+Math.min(100,Math.round(task.progress/task.duration*100))+'%':target.label+' [E]'}
 },
 draw(){const s=gameMode==='solo'?this.ops?.snapshot(player):this.state;if(!s)return;const m=s.mechanism;if(onScreen(m.x,m.y)&&worldGeometry.revealed(player,m,time,false)){ctx.save();ctx.translate(m.x,m.y);Art.round(ctx,-23,-20,46,40,5,'#233f4a','#91d8ce');ctx.fillStyle=time<m.readyAt?'#7f968e':'#8de4c7';ctx.fillRect(-15,-13,30,16);ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillStyle='#d9e9d4';ctx.fillText(m.label,0,-31);ctx.fillText({sector07:'⚡',docks:'↔',ruins:'!',outpost:'⌁'}[m.kind],0,15);ctx.restore()}
  const o=s.objective;if(!o)return;const points=o.kind==='intel'?[...(!o.carried?[o]:[]),{...o.end,upload:true}]:o.kind==='escort'?[o,{...o.end,upload:true}]:[o];for(const p of points){if(!onScreen(p.x,p.y)||!worldGeometry.revealed(player,p,time,false))continue;ctx.save();ctx.translate(p.x,p.y);ctx.lineWidth=2;ctx.strokeStyle=o.contested?'#ef907e':'#f4d391';ctx.fillStyle='#e9c77912';ctx.beginPath();ctx.arc(0,0,o.kind==='beacon'?110:o.kind==='escort'?140:34,0,TAU);ctx.fill();ctx.stroke();if(o.kind==='escort'&&!p.upload){Art.round(ctx,-28,-16,56,32,5,'#7fa39c','#d3e5c2');ctx.fillStyle='#263e4b';ctx.fillRect(12,-12,10,24);for(const y of [-21,16])ctx.fillRect(-18,y,30,5)}else{Art.round(ctx,-16,-16,32,32,4,p.upload?'#44686c':'#a88350','#f4d391');ctx.font='bold 22px monospace';ctx.fillStyle='#fce9b7';ctx.textAlign='center';ctx.fillText(p.upload?'↑':o.kind==='intel'?'◆':'◎',0,8)}ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillStyle='#f4d391';ctx.fillText(p.upload?(o.kind==='escort'?'护送终点':'上传点'):{intel:'情报箱',escort:'运输车',beacon:'撤离信标'}[o.kind],0,-33);ctx.restore()}
 },
 signals(){const labels={skill:'技能',step:'脚步',lock:'撬锁',shot:'枪声',tools:'改装',alarm:'警报',machine:'机关',intel:'情报',radar:'雷达',down:'倒地',objective:'目标',complete:'完成'};for(const n of this.heard.slice(-5)){const x=player.x+Math.cos(n.direction)*93,y=player.y+Math.sin(n.direction)*93;ctx.save();ctx.strokeStyle='#f3ce84a0';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y,80,n.direction-.16,n.direction+.16);ctx.stroke();ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillStyle='#f3d39c';ctx.fillText(labels[n.kind]||'动静',x,y);ctx.restore();if(!this.seenSounds.has(n.id)){this.seenSounds.add(n.id);if(n.kind==='step')sound('step',.18);else if(n.kind==='shot')sound(n.weapon||'USP',.18);else if(n.kind==='lock'||n.kind==='tools')sound('reload',.18);else if(n.kind==='alarm')sound('elite',.14);else if(n.kind==='machine')sound('airdrop',.15)}}if(this.seenSounds.size>128)this.seenSounds.clear();
  if(gameMode==='multi')for(const a of TZNet.state?.peers||[])if(a.downed&&onScreen(a.x,a.y)&&(a.ally||perceive(a))){ctx.save();ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillStyle=a.ally?'#9ce4ce':'#eeb295';ctx.fillText(a.ally?'✚ 等待救援':'倒地',a.x,a.y-25);ctx.restore()}
 },
 minimap(m,s){const state=gameMode==='solo'?this.ops?.snapshot(player):this.state;if(!state)return;m.fillStyle='#91d8ce';m.fillRect(state.mechanism.x*s-2,state.mechanism.y*s-2,4,4);const o=state.objective;if(o){m.fillStyle='#ffdc89';if(!o.carried)m.fillRect(o.x*s-3,o.y*s-3,6,6);if(o.kind==='intel'||o.kind==='escort'){m.strokeStyle='#ffdc89';m.strokeRect(o.end.x*s-3,o.end.y*s-3,6,6)}}if(gameMode==='multi'){m.fillStyle='#80e3cd';for(const p of TZNet.state?.peers||[])if(p.ally)m.fillRect(p.x*s-2,p.y*s-2,4,4)}}
};
$('installMod').addEventListener('click',()=>FieldOps.install());

